/// `func main()` — writes `enum_values()` to stdout as JSON, matching the Go
/// program's `json.NewEncoder(os.Stdout).Encode(values)` (sorted keys, one
/// line, trailing newline). `expect` mirrors Go's `panic(err)`.
pub fn print_enum_values_json() {
    let stdout = std::io::stdout();
    let mut out = stdout.lock();
    serde_json::to_writer(&mut out, &enum_values())
        .expect("enum_values_generated: JSON encode failed");
    out.write_all(b"\n")
        .expect("enum_values_generated: stdout write failed");
}
